/* lib/active_admin/themes/recipes/v3/foundation/tokens.css
 * ActiveAdmin Themes: v3 recipe 1. Application-owned after explicit installation.
 * AA3.5-inspired hierarchy on AA4/Tailwind4; not historical CSS.
 * Native AA pages are recognized by #main-menu. Custom login layouts opt in
 * with data-activeadmin-theme="v3". Loading the Ruby gem never imports this file.
 */
body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"] {
  --aat-font: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --aat-text-size: 0.875rem;
  --aat-line-height: 1.5;
  --aat-space-1: 0.25rem;
  --aat-space-2: 0.5rem;
  --aat-space-3: 0.75rem;
  --aat-space-4: 1rem;
  --aat-space-6: 1.5rem;
  --aat-page-gutter: 1.875rem;
  --aat-radius: 0.25rem;
  --aat-border-width: 1px;
  --aat-control-height: 2.25rem;
  --aat-background: #f3f4f5;
  --aat-surface: #ffffff;
  --aat-subtle: #eef0f2;
  --aat-text: #323537;
  --aat-muted: #535d65;
  --aat-link: #38678b;
  --aat-border: #87929c;
  --aat-chrome: #42494f;
  --aat-chrome-text: #ffffff;
  --aat-selected: #d9e4ec;
  --aat-focus: #175eac;
  --aat-danger: #932419;
  --aat-danger-bg: #fff0ee;
  --aat-success: #245c34;
  --aat-success-bg: #edf7ef;
  --aat-warning: #754600;
  --aat-warning-bg: #fff5dc;
}

/* Follow ActiveAdmin's native persisted theme state. */
html.dark :is(body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"]) {
  --aat-background: #171c21;
  --aat-surface: #222a31;
  --aat-subtle: #2d3740;
  --aat-text: #edf0f2;
  --aat-muted: #bdc7d0;
  --aat-link: #a7d1f3;
  --aat-border: #71808d;
  --aat-chrome: #10171d;
  --aat-selected: #354d60;
  --aat-focus: #f3cf79;
  --aat-danger: #ffc1b8;
  --aat-danger-bg: #4a2525;
  --aat-success: #b5e5c0;
  --aat-success-bg: #223e2b;
  --aat-warning: #f6d892;
  --aat-warning-bg: #44381f;
}

sources.foundation/base:
/* lib/active_admin/themes/recipes/v3/foundation/base.css */
body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"] {
  background: var(--aat-background);
  color: var(--aat-text);
  font-family: var(--aat-font);
  font-size: var(--aat-text-size);
  line-height: var(--aat-line-height);
}

:is(body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"]) :focus-visible {
  outline: 2px solid var(--aat-focus);
  outline-offset: 3px;
}

:is(body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"]) a {
  color: var(--aat-link);
  text-underline-offset: 0.2em;
}

html.dark :is(body:has(:where(#main-menu)), body[data-activeadmin-theme="v3"]) {
  color-scheme: dark;
}

sources.components/navigation:
/* lib/active_admin/themes/recipes/v3/components/navigation.css */
/* Native AA4 drawer dimensions and JS hooks remain framework-owned. */
body:has(:where(#main-menu)) {
  & > div:has(> [data-drawer-target="main-menu"]) {
    background: var(--aat-chrome);
    color: var(--aat-chrome-text);
    border-color: var(--aat-chrome);
    & a, & button, & button svg { color: var(--aat-chrome-text); }
    & :focus-visible { outline-color: #f3cf79; }
  }
  & #main-menu {
    background: var(--aat-surface);
    border-color: var(--aat-border);
    & a, & button { color: var(--aat-text); border-radius: var(--aat-radius); }
    & .selected > a, & a.selected, & a[aria-current="page"] {
      background: var(--aat-selected);
      border-inline-start: 3px solid var(--aat-link);
      font-weight: 700;
    }
    & a:hover, & button:hover { background: var(--aat-subtle); }
  }
  & #user-menu { background: var(--aat-surface); color: var(--aat-text); }
  & #user-menu a { color: var(--aat-text); }
  & [data-test-site-title] { font-size: 1rem; overflow-wrap: anywhere; }
  & [data-test-page-header] {
    background: var(--aat-subtle);
    border-color: var(--aat-border);
    padding: var(--aat-space-4) var(--aat-page-gutter);
    margin-bottom: var(--aat-space-6);
    gap: var(--aat-space-3);
    & h2 { font-size: 1.5rem; line-height: 1.25; overflow-wrap: anywhere; }
    & nav a { color: var(--aat-muted); }
  }
  & [data-test-page-content] { padding-inline: var(--aat-page-gutter); }
  & .action-item-button {
    background: var(--aat-surface);
    color: var(--aat-text);
    border-color: var(--aat-border);
    border-radius: var(--aat-radius);
    min-height: var(--aat-control-height);
  }
}

sources.components/tables:
/* Index presentation only; sorting, selection and pagination stay native. */
body:has(:where(#main-menu)) {
  & .paginated-collection {
    background: var(--aat-surface);
    border-color: var(--aat-border);
    border-radius: var(--aat-radius);
    overflow: visible;
    min-width: 0;
  }
  & .paginated-collection-contents { overflow-x: auto; }
  & .data-table {
    color: var(--aat-text);
    & th, & td { padding: var(--aat-space-2) var(--aat-space-3); }
    & th, & tbody tr { border-color: var(--aat-border); }
    & th { background: var(--aat-subtle); color: var(--aat-text); text-transform: none; font-size: inherit; }
    & th a { color: inherit; }
    & tbody tr:nth-child(even) { background: var(--aat-background); }
    & tbody tr:hover { background: var(--aat-subtle); }
    & tbody tr:has(input[type="checkbox"]:checked) { background: var(--aat-selected); }
    & [data-column="id"], & [data-column="quantity"], & .numeric { text-align: end; font-variant-numeric: tabular-nums; }
    & td { vertical-align: top; max-width: 32rem; overflow-wrap: anywhere; }
    & input[type="checkbox"] { accent-color: var(--aat-link); }
  }
  & .scopes { gap: var(--aat-space-1); }
  & .index-button, & .batch-actions-dropdown-toggle {
    color: var(--aat-text);
    background: var(--aat-surface);
    border-color: var(--aat-border);
    min-height: var(--aat-control-height);
    border-radius: var(--aat-radius);
  }
  & .index-button:hover { background: var(--aat-subtle); }
  & .index-button-selected, & .index-button-selected:hover {
    background: var(--aat-selected);
    box-shadow: inset 0 -3px var(--aat-link);
    font-weight: 700;
  }
  & .scopes-count { background: var(--aat-subtle); color: var(--aat-text); }
  & .paginated-collection-pagination, & .paginated-collection-footer {
    padding: var(--aat-space-2) var(--aat-space-3);
    border-color: var(--aat-border);
    color: var(--aat-muted);
    gap: var(--aat-space-2);
    flex-wrap: wrap;
  }
  & .paginated-collection-pagination a {
    min-height: var(--aat-control-height);
    color: var(--aat-link);
    border-radius: var(--aat-radius);
  }
  & .paginated-collection-pagination a:hover { background: var(--aat-subtle); }
  /* AA4 beta22 exposes the current page via this utility, not aria-current. */
  & .paginated-collection-pagination a.bg-blue-500 {
    background: var(--aat-selected);
    color: var(--aat-text);
    box-shadow: inset 0 -3px var(--aat-link);
    font-weight: 700;
  }
  & .batch-actions-dropdown-menu { background: var(--aat-surface); color: var(--aat-text); }
  & .batch-actions-dropdown-menu a { color: var(--aat-text); }
  & .batch-actions-dropdown-toggle:disabled { opacity: 0.6; cursor: not-allowed; }
  & .blank-slate { padding: var(--aat-space-6); color: var(--aat-muted); }
}
